"""Build idea pages and editable display compositions; all content is local."""
from pathlib import Path
from html import escape
import json
R=Path(__file__).resolve().parents[1]
E=R/'explorations'
DATA=json.loads((E/'directions.json').read_text())
BUSINESS=json.loads((R/'data/business-profile.json').read_text())
PHONE='+91 78942 65632'
DETAILS={
 'letter-and-lid':{'description':'A compact lid grows from the D. Warm custom lettering carries the name, while a small saffron accent keeps the E distinct.','principle':'Symbol and letter work together, as in the integrated initial marks in the references. The composition and artwork are original.','tradeoff':'The lid-to-D relationship adds character, but needs a reduced-size test before it can replace the current lockup.','color':'#852D26','accent':'#E8A535'},
 'odia-first':{'description':'Odia becomes the first thing you read. Rounded, substantial lettering sits above a quiet English name; leaf and terracotta give it a different mood.','principle':'Regional script leads the hierarchy, with English providing an accessible second reading. No temple or ritual motif stands in for the language.','tradeoff':'The generated sketch is a visual direction. Check its letterforms and the proposed transliteration against the exact typeset specimens below with a native Odia reader.','color':'#354A3A','accent':'#A34734'},
 'hindi-signature':{'description':'Bold Devanagari signwriting, a controlled headline and a small steam accent. The English name stays secondary, with vermilion and mustard bringing warmth.','principle':'Borrow the disciplined relationship between expressive script and quiet information seen in the reference signs, without copying their letterforms.','tradeoff':'Steam must stay separate from matras and letters. This proposed Hindi transliteration and the generated drawing require native-reader review.','color':'#A43C2D','accent':'#DBA13C'},
 'current':{'description':'The current serif-and-lifted-lid proposal, expanded into an interior wall, a wide banner, a landscape TV display and a freestanding poster.','principle':'Keep the current name and symbol fixed, and extend the gouache illustration into larger spaces.','tradeoff':'The wall image is a generated spatial concept. The display exports are exact digital compositions, not measured print or installation files.','color':'#852D26','accent':'#E8A535'}
}
ROUTES=[{'slug':'current','name':'The lifted lid','script':'Current proposal','text':'Dum E Odisha'},*DATA['routes']]

def shell(title,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — Dum E Odisha</title><link rel="icon" href="../assets/logo/favicon.png"><link rel="stylesheet" href="explorations.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><a class="brand" href="../index.html">DUM E ODISHA</a><nav class="toplinks" aria-label="Explorations"><a href="index.html">All ideas</a><a href="type-lab.html">Odia & Hindi</a><a href="../index.html#ideas">Brand guide ↗</a></nav></header><main class="wrap" id="main">{body}<footer><a href="index.html">Compare all directions ←</a><span>Explorations / 17 October 2026 / owner review pending</span></footer></main></body></html>'''

def font_panel(script,compact=False):
 is_odia=script=='odia'
 text=DATA['scriptDrafts'][script]['text'];lang='or' if is_odia else 'hi'
 label='Odia' if is_odia else 'Hindi / Devanagari'
 families=['Noto Serif Oriya','Noto Sans Oriya'] if is_odia else ['Noto Serif Devanagari','Noto Sans Devanagari']
 css=['odia-serif','odia-sans'] if is_odia else ['hindi-serif','hindi-sans']
 return f'''<div class="specimen-panel"><h3>{label}</h3><label class="font-choice">Compare the lettering <select data-specimen="{script}-specimen"><option value="{css[0]}">{families[0]}</option><option value="{css[1]}">{families[1]}</option></select></label><div id="{script}-specimen" class="specimen {css[0]}" lang="{lang}">{text}</div><div class="font-label">DUM E ODISHA / proposed transliteration</div><p class="font-help">The font specimen is live typeset text. It preserves the supplied Unicode string rather than relying on generated pixels. Native-speaker spelling and shaping review is still pending.</p></div>'''

FONT_SCRIPT='''<script>document.querySelectorAll('[data-specimen]').forEach(select=>select.addEventListener('change',()=>{document.getElementById(select.dataset.specimen).className='specimen '+select.value}));</script>'''

for route in ROUTES:
 slug=route['slug'];d=DETAILS[slug]
 logo='../assets/logo/primary.png' if slug=='current' else f'assets/{slug}-logo-preview.webp'
 variant='' if slug=='current' else '<p class="small">Generated lettering sketch. Script details are exploratory; the typeset proof below preserves the exact proposed text.</p>' if slug!='letter-and-lid' else '<p class="small">Original generated lettering exploration; raster artwork.</p>'
 body=f'''<div class="intro"><p class="eyebrow">{'The current proposal, applied' if slug=='current' else 'New identity exploration / '+route['script']}</p><h1>{route['name']}</h1><p class="lead">{d['description']}</p></div><div class="two-col"><div class="logo-stage"><img src="{logo}" alt="{escape(route['name'])} logo exploration"></div><div><span class="tag">{'Current proposed system' if slug=='current' else 'A distinct idea / not adopted'}</span><h2>The idea behind<br>the lettering.</h2><p>{d['principle']}</p><p class="note">{d['tradeoff']}</p>{variant}<div class="swatch-row"><span class="swatch" style="background:{d['color']};color:#FFF6E7">{d['color']}</span><span class="swatch" style="background:{d['accent']};color:{'#29231F' if d['accent'] in ['#E8A535','#DBA13C'] else '#FFF6E7'}">{d['accent']}</span></div></div></div>'''
 if slug in ['odia-first','hindi-signature']:
  body+='<section class="section"><p class="eyebrow">The exact name / compare real fonts</p><h2>Give the script<br>room to speak.</h2>'+font_panel('odia' if slug=='odia-first' else 'hindi')+FONT_SCRIPT+'</section>'
 body+=f'''<section class="section"><p class="eyebrow">01 / At architectural scale</p><h2>A wall with character.</h2><figure class="gallery-figure"><a href="assets/{slug}-wall.png"><img class="image-full" src="assets/{slug}-wall.webp" alt="Generated wall and takeaway-counter concept for {route['name']}"></a><figcaption>Generated interior and wall concept, not the actual restaurant. Lettering in spatial mockups is illustrative.</figcaption></figure><a href="assets/{slug}-wall.png" download>Download wall concept PNG ↓</a></section>
 <section class="section"><p class="eyebrow">02 / A wide welcome</p><h2>The horizontal banner.</h2><figure class="gallery-figure"><img class="image-full" src="assets/{slug}-banner.png" width="1920" height="640" alt="Wide brand banner for {route['name']}"><figcaption>1920 × 640 px / digital banner layout</figcaption></figure><div class="links"><a href="assets/{slug}-banner.png" download>Download banner PNG ↓</a><a href="{slug}-banner.html">Open editable banner ↗</a></div></section>
 <section class="section"><p class="eyebrow">03 / On screen & on the floor</p><h2>One name.<br>A bigger presence.</h2><div class="mockup-pair"><div><div class="screen-scene"><div class="screen-bezel"><img src="assets/{slug}-tv.png" width="1920" height="1080" alt="TV brand-display design for {route['name']}"></div><div class="screen-foot"></div><div class="screen-base"></div></div><h3 style="margin-top:25px">The TV display</h3><p class="small">1920 × 1080 px / 16:9 brand holding slide. No invented menu or prices.</p><div class="links"><a href="assets/{slug}-tv.png" download>Download TV PNG ↓</a><a href="{slug}-tv.html">Open editable TV layout ↗</a></div></div><div><div class="standee-scene"><img src="assets/{slug}-standee.png" width="900" height="1800" alt="Tall freestanding-poster concept for {route['name']}"></div><h3 style="margin-top:25px">The tall standee</h3><p class="small">900 × 1800 px / layout concept; supplier dimensions and print proof required.</p><div class="links"><a href="assets/{slug}-standee.png" download>Download poster PNG ↓</a><a href="{slug}-standee.html">Open editable poster ↗</a></div></div></div></section>
 <p class="note">All artwork here is a proposal. New scripts and letterforms need owner selection, native-reader review where relevant, vector production and real-scale proofing before installation. The current brand assets remain unchanged.</p>'''
 (E/f'{slug}.html').write_text(shell(route['name'],body))
 for medium,w,h in [('banner',1920,640),('tv',1920,1080),('standee',900,1800)]:
  canvas=f'''<div class="canvas {medium}" style="--brand:{d['color']};--accent:{d['accent']}"><img class="mark" src="{logo}" alt="{escape(route['name'])} logo"><h1 contenteditable="true" aria-label="Editable campaign headline">{'Lift the lid.<br>Make room for flavour.' if medium=='banner' else 'Flavour in<br>Every Layer.'}</h1><img class="food" src="../assets/illustration/lifted-lid.webp" alt="Generated gouache-style biryani illustration"><div class="details">Bhubaneswar · Catering & bulk orders <span>{PHONE} · @dum_e_odisha</span></div></div>'''
  html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(route['name'])} / {medium}</title><link rel="stylesheet" href="displays.css"><style>@page{{size:{w}px {h}px;margin:0}}</style></head><body><div class="toolbar"><a href="{slug}.html">← Back to this idea</a><p>{w} × {h} px / {medium}. Click the headline to edit. Review wrapping before export.</p><button type="button" onclick="window.print()">Print / save PDF proof</button><p class="small">Digital design proposal. Fonts and artwork are raster/live text as supplied; no print-size or installation approval.</p></div><div class="stage">{canvas}</div></body></html>'''
  (E/f'{slug}-{medium}.html').write_text(html)

cards=''
for i,route in enumerate(ROUTES):
 slug=route['slug'];img='../assets/logo/primary.png' if slug=='current' else f'assets/{slug}-logo-preview.webp'
 cards+=f'''<article class="route-card"><a href="{slug}.html" aria-label="View {route['name']}"><img src="{img}" alt="{route['name']} identity"></a><span class="number">{'00 / CURRENT' if i==0 else f'0{i} / '+route['script'].upper()}</span><h2>{route['name']}</h2><p>{DETAILS[slug]['description']}</p><a class="view" href="{slug}.html">View this idea & mockups ↗</a></article>'''
comparison=''.join(f'<tr><td>{r["name"]}</td><td>{r["script"]}</td><td>{DETAILS[r["slug"]]["tradeoff"]}</td></tr>' for r in ROUTES)
body=f'''<div class="intro"><p class="eyebrow">Dum E Odisha / The idea collection</p><h1>One name.<br>A few new possibilities.</h1><p class="lead">Choose a direction to see its logo, wall concept, wide banner, TV display and tall poster. The three new ideas study the lettering relationships in your references while keeping the artwork original.</p><div class="links"><a href="type-lab.html">Explore Odia & Hindi fonts ↗</a><a href="reference-study.html">How the screenshots informed the work ↗</a></div></div><div class="route-grid">{cards}</div><section class="section"><h2>Compare the directions.</h2><div class="comparison-table"><table><thead><tr><th>Direction</th><th>Script</th><th>What to weigh</th></tr></thead><tbody>{comparison}</tbody></table></div><p class="note">These are alternatives to compare, not a record of owner selection. Odia/Hindi spellings and generated letterforms remain pending native-reader review.</p></section>'''
food_data=E/'round-02/directions.json'
if food_data.exists():
 food=json.loads(food_data.read_text())
 food_cards=''.join(f'<article class="route-card"><a href="round-02/{r["slug"]}.html"><img src="round-02/assets/{r["slug"]}-logo.webp" alt="{r["name"]} logo"></a><span class="number">ROUND 02 / {r["family"].upper()}</span><h2>{r["name"]}</h2><p>{r["description"]}</p><a class="view" href="round-02/{r["slug"]}.html">View logo & brand world ↗</a></article>' for r in food['routes'])
 promotion='<section class="section" id="food-round"><p class="eyebrow">Latest / Based on your food-brand screenshots</p><h2>Four new brand personalities.</h2><p>Original character, wordmark, negative-space and illustrated identities, each with a coordinated packaging board.</p><div class="links"><a href="round-02/index.html">Open the new collection ↗</a><a href="round-02/reference-study.html">Read the close reference study ↗</a></div><div class="route-grid">'+food_cards+'</div></section><section class="section"><h2>Earlier lettering & script ideas</h2></section>'
 body=body.replace('<div class="route-grid">',promotion+'<div class="route-grid">',1)
if (E/'dum-club-refinement/index.html').exists():
 club='<section class="section"><p class="eyebrow">Latest / Focused refinement of your original logo</p><div class="two-col"><img src="dum-club-refinement/assets/negative-space-primary.png" style="width:100%;max-height:300px;object-fit:contain" alt="Refined Dum Club logo with a negative-space rice counter"><div><h2>The Dum Club.<br>Same base idea, refined.</h2><p>Faithful and negative-space alternatives, a measured golden-ratio hierarchy, colour/one-ink proofs and a coordinated brand world.</p><a href="dum-club-refinement/index.html">Open the focused refinement ↗</a></div></div></section>'
 body=body.replace('<section class="section" id="food-round">',club+'<section class="section" id="food-round">',1)
if (E/'round-03/index.html').exists():
 latest='''<section class="section"><p class="eyebrow">New / Image-only and mixed-script logos</p><div class="two-col"><img src="round-03/assets/handi-host.png" style="width:100%;max-height:330px;object-fit:contain" alt="Handi Host pictorial logo without lettering"><div><h2>A picture.<br>Hindi & Odia, mixed.</h2><p>A lettering-free cooking-pot host, plus genuine Hindi/English and Odia/English wordmarks. Compare initial, middle and ending script positions.</p><div class="links"><a href="round-03/index.html">Compare the three new ideas ↗</a><a href="round-03/hindi.html">Hindi ↗</a><a href="round-03/odia.html">Odia ↗</a></div></div></div></section>'''
 body=body.replace('<section class="section">',latest+'<section class="section">',1)
(E/'index.html').write_text(shell('Explore the ideas',body))
body='''<div class="intro"><p class="eyebrow">The type lab / Odia & Hindi</p><h1>Let the language<br>lead the identity.</h1><p class="lead">Compare serif and sans-serif lettering in two scripts. These are actual local Noto font specimens, not generated pictures of letters. The English name remains Dum E Odisha.</p></div>'''+font_panel('odia')+font_panel('hindi')+FONT_SCRIPT+'''<section class="section"><h2>What stays fixed.</h2><p>Keep every character and mark in the proposed name intact. Symbol accents must sit outside the letters, matras and script joins. A small English name underneath can support readers unfamiliar with the script.</p><p class="note">Odia proposal: <span lang="or" class="odia-serif script-reference">ଦମ୍ ଏ ଓଡ଼ିଶା</span>. Hindi proposal: <span lang="hi" class="hindi-serif script-reference">दम ए ओडिशा</span>. These are draft transliterations, not native-reviewed final names. Verify the preferred spelling, pronunciation and matra/virama rendering with an Odia/Hindi reader before adopting a logo.</p><div class="links"><a href="odia-first.html">View the Odia direction ↗</a><a href="hindi-signature.html">View the Hindi direction ↗</a></div><h3>Font sources & licensing</h3><p class="small">Noto Serif Oriya, Noto Sans Oriya, Noto Serif Devanagari and Noto Sans Devanagari are bundled unmodified from the official Google Fonts repository with their SIL Open Font License files. “Oriya” is the upstream family name; the language is presented as Odia here.</p><div class="links"><a href="fonts/notoseriforiya-OFL.txt">Odia serif license</a><a href="fonts/notosansoriya-OFL.txt">Odia sans license</a><a href="fonts/notoserifdevanagari-OFL.txt">Hindi serif license</a><a href="fonts/notosansdevanagari-OFL.txt">Hindi sans license</a><a href="fonts/provenance.json">Exact source & file hashes</a></div></section>'''
(E/'type-lab.html').write_text(shell('Odia & Hindi type lab',body))
observations=''.join('<section class="section"><h2>Reference '+str(i+1)+'</h2><p>'+escape(r['observations'])+'</p><p class="note">'+escape(r['use'])+'</p></section>' for i,r in enumerate(DATA['referenceAnalysis']))
body='''<div class="intro"><p class="eyebrow">Reference study / supplied screenshots</p><h1>Study the relationships.<br>Build an original mark.</h1><p class="lead">The references show integrated symbols, script-led names, carefully weighted secondary English text, and logos tested against real material backgrounds. Those are the principles explored here.</p></div>'''+observations+'''<section class="section"><h2>From reference to these ideas</h2><p>Letter & lid explores a food cue integrated with a Latin initial. Odia at heart gives the regional script the largest voice. Dum, in Devanagari pairs sign-painted weight with a restrained aroma accent. The current lifted-lid logo remains available as a fourth comparison.</p><p class="note">The screenshots are user-supplied reference material attributed in the images to graphic_dada. They are not our artwork, an asset library or permission to reproduce those businesses' logos. No claims about their authorship, effectiveness or font identities have been inferred.</p><div class="references"><a href="references/lettering-reference-01.png"><img src="references/lettering-reference-01.png" alt="First user-supplied logo reference screenshot"></a><a href="references/lettering-reference-02.png"><img src="references/lettering-reference-02.png" alt="Second user-supplied logo reference screenshot"></a></div></section>'''
(E/'reference-study.html').write_text(shell('Reference study',body))
print('Built the idea collection, four direction pages, type lab, reference study and twelve editable display layouts.')
